271	    response.writeHead(200, { "Content-Type": mime[extname(file)] ?? "application/octet-stream", "X-Content-Type-Options": "nosniff" });
272	    response.end(readFileSync(file));
273	  }
274	}
275	
276	function isStatus(value: unknown): value is PollStatus {
277	  return typeof value === "string" && (STATUSES as readonly string[]).includes(value);
278	}
279	
280	type ParsePollResult =
281	  | { ok: true; input: NewPollInput }
282	  | { ok: false; reason: string; pollId: string };
283	
284	/**
285	 * Validates a draft creation payload: all existing poll fields, a non-empty
286	 * list of distinct member commitments and at least two options with unique
287	 * ids. Returns a machine-readable error code on failure.
288	 */
289	function parseNewPoll(body: unknown): ParsePollResult {
290	  if (typeof body !== "object" || body === null) return { ok: false, reason: "invalid_poll", pollId: "unknown" };
291	  const b = body as Record<string, unknown>;
292	  const pollId = typeof b.id === "string" && b.id.trim() ? b.id : "unknown";
293	  const fail = (reason: string): ParsePollResult => ({ ok: false, reason, pollId });
294	  if (!isNonEmptyString(b.id, 128)) return fail("invalid_poll_id");
295	  if (!isNonEmptyString(b.title)) return fail("invalid_poll");
296	  if (!isNonEmptyString(b.summary)) return fail("invalid_poll");
297	  if (!isNonEmptyString(b.description, 20_000)) return fail("invalid_poll");
298	  if (!isNonEmptyString(b.organizer)) return fail("invalid_poll");
299	  if (!isIsoDate(b.publishedAt) || !isIsoDate(b.closesAt)) return fail("invalid_poll_dates");
300	  if (Date.parse(b.closesAt as string) <= Date.parse(b.publishedAt as string)) return fail("invalid_poll_dates");
301	  if (!Array.isArray(b.options) || b.options.length < 2) return fail("invalid_options");
302	  const optionIds = new Set<string>();
303	  const options: { id: string; label: string }[] = [];
304	  for (const option of b.options) {
305	    if (typeof option !== "object" || option === null) return fail("invalid_options");
306	    const { id, label } = option as { id?: unknown; label?: unknown };
307	    if (!isNonEmptyString(id, 128) || !isNonEmptyString(label)) return fail("invalid_options");
308	    if (optionIds.has(id)) return fail("duplicate_option_id");
309	    optionIds.add(id);
310	    options.push({ id, label });
311	  }
312	  if (!Array.isArray(b.commitments) || b.commitments.length === 0) return fail("invalid_commitments");
313	  const commitments: string[] = [];
314	  for (const commitment of b.commitments) {
315	    if (!isCommitment(commitment)) return fail("invalid_commitments");
316	    if (commitments.includes(commitment)) return fail("duplicate_commitment");
317	    commitments.push(commitment);
318	  }
319	  return {
320	    ok: true,
321	    input: {
322	      id: b.id, title: b.title, summary: b.summary, description: b.description, organizer: b.organizer,
323	      publishedAt: new Date(b.publishedAt).toISOString(), closesAt: new Date(b.closesAt).toISOString(),
324	      options, commitments
325	    }
326	  };
327	}
328	
329	export type { AuditEvent };
