Build WHERE clauses:
```ts
const conditions: string[] = []; const params: (string|number)[] = [];
if (query.pollId) { conditions.push("poll_id = ?"); params.push(query.pollId); }
if (query.action) { conditions.push("action = ?"); params.push(query.action); }
if (query.result) { conditions.push("result = ?"); params.push(query.result); }
if (query.from) { conditions.push("at >= ?"); params.push(query.from); }  // normalized ISO
if (query.to) { conditions.push("at <= ?"); params.push(query.to); }
const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
const total = (db.prepare(`SELECT count(*) AS count FROM audit_events ${where}`).get(...params) as {count:number}).count;
const rows = db.prepare(`SELECT * FROM audit_events ${where} ORDER BY at DESC, id DESC LIMIT ? OFFSET ?`).all(...params, pageSize, (page-1)*pageSize);
const totalPages = Math.ceil(total / pageSize);
```

