      const audit = async (query: string) => {
        const response = await fetch(`${base}/api/admin/audit${query}`, { headers: { "X-Admin-Token": ADMIN_TOKEN } });
        return { status: response.status, body: await response.json() as AuditPage & { error?: string } };
